// Définit toutes les recherches à effectuer
const queries = [
  // FRANCE
  { sector: 'restaurant', city: 'Paris', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'restaurant', city: 'Lyon', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'restaurant', city: 'Marseille', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'restaurant', city: 'Bordeaux', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'salon coiffure', city: 'Paris', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'salon coiffure', city: 'Lyon', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'boutique vêtements', city: 'Paris', country: 'France', lang: 'fr', flag: '🇫🇷' },
  { sector: 'artisan plombier', city: 'Paris', country: 'France', lang: 'fr', flag: '🇫🇷' },
  // BELGIQUE
  { sector: 'restaurant', city: 'Bruxelles', country: 'Belgique', lang: 'fr', flag: '🇧🇪' },
  { sector: 'salon coiffure', city: 'Bruxelles', country: 'Belgique', lang: 'fr', flag: '🇧🇪' },
  { sector: 'restaurant', city: 'Liège', country: 'Belgique', lang: 'fr', flag: '🇧🇪' },
  // ESPAGNE
  { sector: 'restaurante', city: 'Madrid', country: 'España', lang: 'es', flag: '🇪🇸' },
  { sector: 'peluqueria', city: 'Barcelona', country: 'España', lang: 'es', flag: '🇪🇸' },
  { sector: 'restaurante', city: 'Barcelona', country: 'España', lang: 'es', flag: '🇪🇸' },
  // ITALIE
  { sector: 'ristorante', city: 'Milano', country: 'Italia', lang: 'it', flag: '🇮🇹' },
  { sector: 'parrucchiere', city: 'Roma', country: 'Italia', lang: 'it', flag: '🇮🇹' },
  { sector: 'ristorante', city: 'Roma', country: 'Italia', lang: 'it', flag: '🇮🇹' },
  // CAMEROUN
  { sector: 'restaurant', city: 'Douala', country: 'Cameroun', lang: 'fr', flag: '🇨🇲' },
  { sector: 'salon coiffure', city: 'Douala', country: 'Cameroun', lang: 'fr', flag: '🇨🇲' },
  { sector: 'restaurant', city: 'Yaoundé', country: 'Cameroun', lang: 'fr', flag: '🇨🇲' },
  { sector: 'boutique', city: 'Douala', country: 'Cameroun', lang: 'fr', flag: '🇨🇲' }
];

return queries.map(q => ({ json: q }));

// Parse les résultats et enrichit chaque lead
const results = $json.results || [];
const query = $('Définir les recherches').item.json;

return results.map(place => ({
  json: {
    place_id: place.place_id,
    nom: place.name,
    adresse: place.formatted_address || '',
    secteur: query.sector,
    ville: query.city,
    pays: query.country,
    flag: query.flag,
    note_google: place.rating || '',
    nb_avis: place.user_ratings_total || 0,
    a_site_web: place.website ? 'OUI' : 'NON',
    statut: 'NOUVEAU',
    date_ajout: new Date().toISOString().split('T')[0],
    // Les détails (tel/email) seront récupérés ensuite
    telephone: '',
    email: '',
    site_web: place.website || ''
  }
}));

const detail = $json.result || {};
const lead = $('Filtre: PAS de site web').item.json;

const tel = detail.international_phone_number || detail.formatted_phone_number || '';
// Nettoyage du numéro pour WhatsApp (supprime espaces et tirets)
const telWA = tel.replace(/[\s\-\(\)]/g, '');

return [{
  json: {
    ...lead,
    telephone: tel,
    telephone_wa: telWA,
    email: detail.email || '',
    peut_whatsapp: telWA.length > 8 ? 'OUI' : 'NON',
    peut_email: (detail.email || '').includes('@') ? 'OUI' : 'NON'
  }
}];
